<script setup lang="ts">
const {t}=useI18n(),{bizErrorMessage}=useBizError()
const kind=ref('blacklist'),data=ref<any>(null),status=ref<any>(null),loading=ref(true),busy=ref(false),error=ref(''),address=ref(''),reason=ref(''),page=ref(1)
let generation=0
onBeforeUnmount(()=>generation++)
const dirty=computed(()=>!!address.value.trim()||!!reason.value.trim())
defineExpose({dirty,pending:busy})
const statusError=ref('')
const loadStatus=async()=>{statusError.value='';status.value=await httpRequest('/api/system/limiter/status',{onError:e=>statusError.value=bizErrorMessage(e)})}
const load=async()=>{const current=++generation;loading.value=true;error.value='';data.value=null;try{const result=await httpRequest('/api/system/limiter/'+kind.value,{params:{page:page.value,per_page:20},onError:e=>{if(current===generation)error.value=bizErrorMessage(e)}});if(current===generation)data.value=result}finally{if(current===generation)loading.value=false}}
onMounted(()=>{loadStatus();load()})
watch(kind,()=>{page.value=1;load()})
const mutate=async(id?:number)=>{if(busy.value)return;busy.value=true;error.value='';try{const result=await httpRequest('/api/system/limiter/'+kind.value+(id?'/'+id:''),{method:id?'DELETE':'POST',body:id?undefined:{ip_address:address.value.trim(),reason:reason.value.trim()},onError:e=>error.value=bizErrorMessage(e)});if(result){address.value='';reason.value='';await load()}}finally{busy.value=false}}
const columns=computed(()=>[{key:'ip_address',label:t('presentation.ip')},{key:'reason',label:t('presentation.reason'),wrap:true},{key:'timestamp',label:t('common.dates.created')},{key:'actions',label:t('common.fields.action'),align:'right' as const}])
</script>
<template><WCard id="s-ip" flush><div class="heading"><h2>{{t('presentation.access')}}</h2><p>{{t('presentation.access-hint')}}<span v-if="status"> {{t('presentation.client-ip')}} {{status.client_ip}}</span></p></div><WTabs v-model="kind" :label="t('presentation.access')" :items="['blacklist','whitelist'].map(key=>({key,label:t('presentation.'+key)+(status?' · '+t(status[key]?'tenant-list.active':'tenant-list.inactive'):''),disabled:busy}))" inset/><WAlert v-if="statusError" tone="block" :title="statusError"><WButton :disabled="busy" @click="loadStatus">{{t('dn.list.retry')}}</WButton></WAlert><WAlert v-if="error" tone="block" :title="error"><WButton :disabled="busy" @click="load">{{t('dn.list.retry')}}</WButton></WAlert><form @submit.prevent="mutate()"><WField :label="t('presentation.ip')" required><WInput v-model="address" required :disabled="busy"/></WField><WField :label="t('presentation.reason')"><WInput v-model="reason" :maxlength="255" :disabled="busy"/></WField><WButton type="submit" :loading="busy">{{t('presentation.add-ip')}}</WButton></form><WTable :columns="columns" :rows="data?.items||[]" :loading="loading" inset><template #cell-timestamp="{row}">{{$dayjs(row.timestamp)}}</template><template #cell-actions="{row}"><WButton size="sm" variant="danger" :disabled="busy" @click="mutate(row.id)">{{t('button.delete')}}</WButton></template></WTable><footer><WPagination :page="page" :page-size="20" :total="data?.total" show-total @update:page="value=>{page=value;load()}"/></footer></WCard></template>
<style scoped>.heading{padding:16px 24px}h2{font-size:16px;line-height:24px;font-weight:600;margin:0}p{font-size:13px;line-height:20px;color:var(--w-text-3);margin:4px 0 0}form{display:flex;align-items:end;gap:16px;flex-wrap:wrap;padding:16px 24px;border-bottom:1px solid var(--w-line)}form>.w-field{flex:1;min-width:200px}footer{padding:16px 24px}</style>
